<script setup lang="ts">
import {ref} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {newWageEvidence} from '../annualWages'
import {validMonth} from '../payrollUi'
import {supplementalSourceName} from '../supplemental'
import type {SupplementalProposal,SupplementalSourcePage} from '../supplemental'
import WageEventFields from './WageEventFields.vue'
const props=defineProps<{proposals:SupplementalProposal[];companyId:string;employeeId:string;disabled:boolean}>(),{api,current,store,english,message,base}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
const loading=ref<Record<string,boolean>>({}),errors=ref<Record<string,string>>({}),sources=ref<Record<string,SupplementalSourcePage>>({}),revisions=new Map<string,number>()
function add(){props.proposals.push({id:crypto.randomUUID(),originMonth:'',settlementMonth:'',source:{kind:'normal',batchId:null,openingVersion:null,snapshotHash:''},items:[],evidenceReference:''})}
function invalidate(p:SupplementalProposal){revisions.set(p.id,(revisions.get(p.id)||0)+1);p.source={kind:'normal',batchId:null,openingVersion:null,snapshotHash:''};delete sources.value[p.id];loading.value[p.id]=false;errors.value[p.id]=''}
async function lookup(p:SupplementalProposal){if(props.disabled||!validMonth(p.originMonth)||!props.employeeId)return;const rev=(revisions.get(p.id)||0)+1;revisions.set(p.id,rev);const month=p.originMonth,employee=props.employeeId,captured=store.value;loading.value[p.id]=true;errors.value[p.id]='';p.source={kind:'normal',batchId:null,openingVersion:null,snapshotHash:''};delete sources.value[p.id];try{const v=await api().get<SupplementalSourcePage>(`/supplemental-sources?companyId=${encodeURIComponent(props.companyId)}&employeeId=${encodeURIComponent(employee)}&month=${month}`);if(!current()||captured!==store.value||revisions.get(p.id)!==rev||employee!==props.employeeId||month!==p.originMonth||!props.proposals.includes(p))return;if(v.companyId!==props.companyId||v.employeeId!==employee||v.month!==month||!v.source?.snapshotHash)throw new Error(x('没有可用原来源；核对原已发布工资或外部实际月份。','No original source. Review published payroll or actual opening month.'));p.source=v.source;sources.value[p.id]=v}catch(e){if(current()&&revisions.get(p.id)===rev)errors.value[p.id]=message(e)}finally{if(revisions.get(p.id)===rev)loading.value[p.id]=false}}
function addItem(p:SupplementalProposal){p.items.push({itemId:crypto.randomUUID(),label:'',kind:'wage_event',amount:'',eventEvidence:{...newWageEvidence(p.originMonth),settlementMonth:p.settlementMonth}})}
</script>
<template><section class="wf-section"><h3>{{x('独立补发新差额','New supplemental differences')}}</h3><p class="wf-hint">{{x('这里只填写尚未入账的新金额；原已算未付工资必须在原单付款。每项保留原贡献月、结算月和原来源；保存后仍须提交同一工资变更审批。','Enter only new unrecognised amounts. Pay already calculated wages on the original payroll. Each proposal keeps its original contribution month, settlement month and source, and uses the same pay change approval.')}}</p><article v-for="(p,index) in proposals" :key="p.id" class="wf-section"><h4>{{x('补发方案','Supplemental proposal')}} {{index+1}}</h4><div class="wf-grid"><label>{{x('原贡献月份','Original contribution month')}}<input v-model="p.originMonth" type="month" required :aria-label="x('原贡献月份','Original contribution month')+' '+(index+1)" @update:model-value="invalidate(p)"></label><label>{{x('补发结算月份','Supplemental settlement month')}}<input v-model="p.settlementMonth" type="month" required :aria-label="x('补发结算月份','Supplemental settlement month')+' '+(index+1)"></label></div><button type="button" :disabled="disabled||loading[p.id]||!employeeId||!validMonth(p.originMonth)" @click="lookup(p)">{{x('读取原来源','Load original source')}}</button><p v-if="loading[p.id]" role="status">{{x('读取原来源中…','Loading original source…')}}</p><p v-if="errors[p.id]" role="alert">{{errors[p.id]}}</p><p v-if="p.source.snapshotHash" class="wf-hint">{{x('原来源（只读）','Original source (read only)')}}: {{supplementalSourceName(p.source.kind,english())+' '+(p.source.batchId||p.source.openingVersion||'')}} · {{p.source.snapshotHash}}</p><template v-if="sources[p.id]"><p>{{x('原工资总额／原单现金未付','Original gross / original cash remaining')}}: {{sources[p.id].grossPay??x('未知','Unknown')}} / {{sources[p.id].originalCashRemaining??x('未知','Unknown')}}</p><RouterLink v-if="p.source.batchId" :to="base+'/payroll-batches/'+p.source.batchId">{{x('查看原工资及付款','View original payroll and payments')}}</RouterLink><p v-for="code in sources[p.id].issues" :key="code">{{code}}</p></template><label>{{x('补发依据','Supplemental evidence')}}<textarea v-model="p.evidenceReference" required maxlength="1000" :aria-label="x('补发依据','Supplemental evidence')+' '+(index+1)"/></label><article v-for="(item,i) in p.items" :key="item.itemId||i" class="wf-section"><div class="wf-grid"><label>{{x('补发项目名称','Supplemental item label')}}<input v-model="item.label" required maxlength="100" :aria-label="x('补发项目名称','Supplemental item label')+' '+(i+1)"></label><label>{{x('补发项目金额','Supplemental item amount')}}<input v-model="item.amount" required inputmode="decimal" :aria-label="x('补发项目金额','Supplemental item amount')+' '+(i+1)"></label></div><WageEventFields v-if="item.eventEvidence" :value="item.eventEvidence" :disabled="disabled" allow-omitted/><button type="button" :disabled="disabled" @click="p.items.splice(i,1)">{{x('移除补发项目','Remove supplemental item')}}</button></article><button type="button" :disabled="disabled||p.items.length>=20" @click="addItem(p)">{{x('添加补发项目','Add supplemental item')}}</button><button type="button" :disabled="disabled" @click="proposals.splice(index,1)">{{x('移除补发方案','Remove supplemental proposal')}}</button></article><button type="button" :disabled="disabled||!employeeId||proposals.length>=20" @click="add">{{x('添加补发方案','Add supplemental proposal')}}</button></section></template>
<style scoped>p{overflow-wrap:anywhere}</style>
